	if err != nil {
		t.Fatalf("failed to upload compose file: %v", err)
	}

	// Verify file exists
	exists, err := client.FileExists(t.Context(), remotePath)
	if err != nil {
		t.Fatalf("failed to check file exists: %v", err)
	}
