    21→// ContainerPool manages a pool of SSH containers for parallel test execution.
    22→type ContainerPool struct {
    23→	size          int
    24→	containers    chan *SSHDockerContainer
    25→	allContainers []*SSHDockerContainer
    26→	initOnce      sync.Once
    27→	initErr       error
    28→	mu            sync.Mutex
    29→	closed        bool
    30→}
    31→
    32→// NewContainerPool creates a new container pool with the specified size.
    33→func NewContainerPool(size int) *ContainerPool {
    34→	if size < 1 {
    35→		size = 1
    36→	}
    37→	return &ContainerPool{
    38→		size:       size,
    39→		containers: make(chan *SSHDockerContainer, size),
    40→	}
    41→}
    42→
    43→// initialize creates all containers in the pool.
    44→func (p *ContainerPool) initialize(t *testing.T) error {
    45→	p.initOnce.Do(func() {
    46→		t.Logf("Initializing container pool with %d containers...", p.size)
    47→
    48→		p.allContainers = make([]*SSHDockerContainer, 0, p.size)
    49→
    50→		var wg sync.WaitGroup
    51→		errors := make([]error, p.size)
    52→		containers := make([]*SSHDockerContainer, p.size)
    53→
    54→		for i := 0; i < p.size; i++ {
    55→			wg.Add(1)
    56→			go func(idx int) {
    57→				defer wg.Done()
    58→				container, err := createPoolContainer(t, idx)
    59→				if err != nil {
    60→					errors[idx] = err
    61→					return
    62→				}
    63→				containers[idx] = container
    64→			}(i)
    65→		}
    66→
    67→		wg.Wait()
    68→
    69→		for i, err := range errors {
    70→			if err != nil {
    71→				p.initErr = fmt.Errorf("failed to create container %d: %w", i, err)
    72→				for _, c := range containers {
    73→					if c != nil && c.Container != nil {
    74→						_ = c.Container.Terminate(context.Background())
    75→					}
    76→				}
    77→				return
    78→			}
    79→		}
    80→
    81→		for _, c := range containers {
    82→			p.allContainers = append(p.allContainers, c)
    83→			p.containers <- c
    84→		}
    85→
    86→		t.Logf("Container pool initialized with %d containers", p.size)
    87→	})
    88→
    89→	return p.initErr
    90→}
    91→
    92→// Acquire gets a container from the pool.
    93→func (p *ContainerPool) Acquire(t *testing.T) *SSHDockerContainer {
    94→	t.Helper()
    95→
    96→	if testing.Short() {
    97→		t.Skip("Skipping container-based test in short mode")
    98→	}
    99→
   100→	if err := p.initialize(t); err != nil {
   101→		t.Fatalf("failed to initialize container pool: %v", err)
   102→	}
   103→
   104→	p.mu.Lock()
   105→	if p.closed {
   106→		p.mu.Unlock()
   107→		t.Fatal("container pool is closed")
   108→	}
   109→	p.mu.Unlock()
   110→
   111→	t.Log("Acquiring container from pool...")
   112→	container := <-p.containers
   113→	t.Logf("Acquired container at %s:%d", container.Host, container.Port)
   114→
   115→	cleanupContainer(container)
   116→
   117→	t.Cleanup(func() {
   118→		cleanupContainer(container)
   119→
   120→		p.mu.Lock()
   121→		defer p.mu.Unlock()
   122→
   123→		if !p.closed {
   124→			p.containers <- container
   125→			t.Log("Released container back to pool")
   126→		}
   127→	})
   128→
   129→	return container
   130→}
   131→
   132→// Close terminates all containers in the pool.
   133→func (p *ContainerPool) Close() {
   134→	p.mu.Lock()
   135→	defer p.mu.Unlock()
   136→
   137→	if p.closed {
   138→		return
   139→	}
   140→	p.closed = true
