   146→		if c != nil && c.Container != nil {
   147→			_ = c.Container.Terminate(ctx)
   148→		}
   149→	}
   150→}
   151→
   152→// Size returns the pool size.
   153→func (p *ContainerPool) Size() int {
   154→	return p.size
   155→}
   156→
   157→// cleanupContainer removes test files and stops any running compose stacks.
   158→func cleanupContainer(c *SSHDockerContainer) {
   159→	commands := []string{
